import math
from numbers import Real


def _number(value):
    if isinstance(value, bool) or not isinstance(value, Real):
        raise TypeError("matrix values must be real numbers")
    value = float(value)
    if not math.isfinite(value):
        raise ValueError("matrix values must be finite")
    return value


def _matrix(value, name):
    if isinstance(value, (str, bytes)) or not value:
        raise ValueError(f"{name} must be a non-empty matrix")
    rows = []
    width = None
    for row in value:
        if isinstance(row, (str, bytes)) or not row:
            raise ValueError(f"{name} rows must be non-empty")
        converted = tuple(_number(item) for item in row)
        if width is None:
            width = len(converted)
        elif len(converted) != width:
            raise ValueError(f"{name} must be rectangular")
        rows.append(converted)
    return tuple(rows)


class PatchClassifier:
    def __init__(self, kernels, biases):
        if isinstance(kernels, (str, bytes)) or not kernels:
            raise ValueError("kernels must be non-empty")
        self._kernels = tuple(_matrix(kernel, "kernel") for kernel in kernels)
        shape = (len(self._kernels[0]), len(self._kernels[0][0]))
        if any((len(kernel), len(kernel[0])) != shape for kernel in self._kernels):
            raise ValueError("kernels must have equal dimensions")
        self._biases = tuple(_number(value) for value in biases)
        if len(self._biases) != len(self._kernels):
            raise ValueError("bias count must match kernel count")

    def predict_proba(self, image):
        image = _matrix(image, "image")
        kh, kw = len(self._kernels[0]), len(self._kernels[0][0])
        if len(image) < kh or len(image[0]) < kw:
            raise ValueError("image is smaller than a kernel")
        scores = []
        for kernel, bias in zip(self._kernels, self._biases):
            total = 0.0
            for top in range(len(image) - kh + 1):
                for left in range(len(image[0]) - kw + 1):
                    response = bias
                    for row in range(kh):
                        for col in range(kw):
                            response += image[top + row][left + col] * kernel[row][col]
                    total += response
            scores.append(total)
        peak = max(scores)
        weights = [math.exp(score - peak) for score in scores]
        denominator = sum(weights)
        return [weight / denominator for weight in weights]

    def predict(self, image):
        probabilities = self.predict_proba(image)
        return max(range(len(probabilities)), key=probabilities.__getitem__)

